import{_ as e,a as i,b as o,c as t,d as r,e as n,f as l,g as s,h as c,i as d,j as p,k as m,l as u,m as _,n as h,o as g,p as f,q as b,r as z,s as v,t as y,u as q,v as w,w as k,x,y as A,z as P,A as T}from"./chunks/ScreenSaver2.C6Ib7NV6.js";import{_ as I}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as N}from"./chunks/UImenu.2mWyDoEW.js";import{_ as L}from"./chunks/3dots_menu.BrLPqWzo.js";import{_ as S,o as M,c as C,a3 as D}from"./chunks/framework.g9mfNVRQ.js";const j=JSON.parse('{"title":"Schermata principale","description":"","frontmatter":{"source_hash":"3c47ed9511","source_commit":"ea9ce3a"},"headers":[],"relativePath":"it/use/mainUI.md","filePath":"it/use/mainUI.md"}'),U={name:"it/use/mainUI.md"};function E(V,a,R,G,O,F){return M(),C("div",null,[...a[0]||(a[0]=[D('<h3 id="meet-the-user-interface" tabindex="-1">Scopri l&#39;interfaccia utente <a class="header-anchor" href="#meet-the-user-interface" aria-label="Permalink to &quot;Scopri l&#39;interfaccia utente {#meet-the-user-interface}&quot;">​</a></h3><p>Benvenuto in xDrip!</p><img src="'+e+'" style="zoom:50%;"><p>Se hai appena configurato xDrip, inizia con le personalizzazioni di base:</p><ol><li><a href="./settings.html">Imposta l&#39;unità con cui visualizzare la glicemia</a></li><li><a href="./alarms.html">Aggiungi gli allarmi</a></li><li>Se colleghi xDrip a un sensore, <a href="./syncsetup.html">condividi i dati con un altro telefono con xDrip</a></li><li>Visualizza xDrip sul telefono quando <a href="./display.html#numbered-wall-on-locked-screen">lo schermo è bloccato</a></li><li>Aggiungi un <a href="#widget">widget</a> alla schermata Home del telefono</li><li>Aggiungi uno <a href="./../smartwatch/smartwatch.html">smartwatch</a></li><li>Condividi i dati con il tuo diabetologo tramite <a href="https://www.tidepool.org/" target="_blank" rel="noreferrer">Tidepool</a>: se hai un account Tidepool, basta <a href="./cloud.html#tidepool">configurare xDrip</a></li><li>Carica i tuoi dati su <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> (consigliato)</li></ol><h3 id="basic-indications" tabindex="-1">Indicazioni di base <a class="header-anchor" href="#basic-indications" aria-label="Permalink to &quot;Indicazioni di base {#basic-indications}&quot;">​</a></h3><p>Quando xDrip riceve i dati vedrai queste indicazioni predefinite.</p><img src="'+i+'" style="zoom:75%;"><ol><li>Quanto tempo fa è stata ricevuta la lettura e qual è la differenza di glicemia rispetto al valore precedente.</li><li>L&#39;ultimo valore di glicemia misurato.</li><li>La tendenza rispetto alla misura precedente.</li></ol><h5 id="trend-arrow" tabindex="-1">Freccia di tendenza <a class="header-anchor" href="#trend-arrow" aria-label="Permalink to &quot;Freccia di tendenza {#trend-arrow}&quot;">​</a></h5><div class="info custom-block"><p class="custom-block-title">Nota</p><p>La freccia indica la tendenza rispetto alla misura precedente; altre app CGM usano un algoritmo per questa indicazione e il risultato potrebbe non coincidere.<br> In caso di letture mancanti, la freccia potrebbe indicare un aumento o un calo rapido: confrontala sempre con l&#39;indicazione in <code>1</code>.</p></div><p>Puoi personalizzare le informazioni mostrate in <code>1</code> con le <a href="./display.html#graph-settings">Impostazioni grafico</a>.</p><p>Puoi <a href="#blood-drop-menu">personalizzare l&#39;aspetto della freccia di tendenza</a> ma non il suo comportamento (userà sempre la differenza con la lettura precedente).</p><p>Ecco come appare la freccia di tendenza classica, che tiene conto della differenza tra la lettura di glicemia precedente e quella attuale.</p><table tabindex="0"><thead><tr><th>Differenza di glicemia (precedente e attuale)</th><th></th></tr></thead><tbody><tr><td>Variazione al massimo di +/- 5 mg/dL (0,28 mmol/L)</td><td><img src="'+o+'" style="zoom:75%;"></td></tr><tr><td>Variazione superiore alla precedente e inferiore a +/- 10 mg/dL (0,56 mmol/L)</td><td><img src="'+t+'" style="zoom:75%;"></td></tr><tr><td>Variazione superiore alla precedente e inferiore a +/- 17,5 mg/dL (0,97 mmol/L)</td><td><img src="'+r+'" style="zoom:75%;"></td></tr><tr><td>Variazione superiore alla precedente</td><td><img src="'+n+'" style="zoom:75%;"></td></tr></tbody></table><h3 id="treatments" tabindex="-1">Trattamenti <a class="header-anchor" href="#treatments" aria-label="Permalink to &quot;Trattamenti {#treatments}&quot;">​</a></h3><p>Puoi registrare i trattamenti con l&#39;icona della siringa.</p><img src="'+l+'" style="zoom:75%;"><p>Aggiungi uno o più elementi al trattamento.</p><h4 id="blood-test" tabindex="-1">Misura capillare <a class="header-anchor" href="#blood-test" aria-label="Permalink to &quot;Misura capillare {#blood-test}&quot;">​</a></h4><p>Viene visualizzata nell&#39;unità selezionata in xDrip.</p><img src="'+s+'" style="zoom:75%;"><h4 id="grams-of-carbs" tabindex="-1">Grammi di carboidrati <a class="header-anchor" href="#grams-of-carbs" aria-label="Permalink to &quot;Grammi di carboidrati {#grams-of-carbs}&quot;">​</a></h4><img src="'+c+'" style="zoom:75%;"><h4 id="units-of-insulin" tabindex="-1">Unità di insulina <a class="header-anchor" href="#units-of-insulin" aria-label="Permalink to &quot;Unità di insulina {#units-of-insulin}&quot;">​</a></h4><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Se hai attivato i <a href="./predictions.html#multiple-insulin-types">tipi di insulina multipli</a>, seleziona anche il tipo di insulina per questo trattamento.</p></div><img src="'+d+'" style="zoom:75%;"><h4 id="time" tabindex="-1">Ora <a class="header-anchor" href="#time" aria-label="Permalink to &quot;Ora {#time}&quot;">​</a></h4><p>E infine l&#39;ora del trattamento (se non è adesso), nel formato 24 ore, con o senza separatore.</p><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Puoi selezionare un orario del trattamento da 23 ore nel passato fino a 1 ora nel futuro.</p></div><img src="'+p+'" style="zoom:75%;"><p>I trattamenti sono validi quando compare il segno di spunta verde nell&#39;angolo in alto a destra. Toccalo per confermare i dati inseriti.</p><img src="'+m+'" style="zoom:75%;"><p>Viene mostrato un riepilogo. Tocca l&#39;icona verde <code>+</code> per confermare o l&#39;icona rossa <code>x</code> per annullare.</p><img src="'+u+'" style="zoom:75%;"><p>Una volta fatto, sul grafico compariranno nuovi simboli.</p><p>Unità e carboidrati appaiono così:</p><img src="'+_+'" style="zoom:75%;"><p>E le misure capillari così (nota che il simbolo è quadrato, a differenza delle <a href="./../calibrate/calibrate.html">calibrazioni</a> che sono rotonde):</p><img src="'+h+'" style="zoom:75%;"><h4 id="edit-and-delete" tabindex="-1">Modificare ed eliminare <a class="header-anchor" href="#edit-and-delete" aria-label="Permalink to &quot;Modificare ed eliminare {#edit-and-delete}&quot;">​</a></h4><p>Quando sono visibili, puoi eliminare i trattamenti così:</p><ul><li>Tocca il trattamento e guarda in fondo allo schermo: tocca Aggiungi nota</li></ul><div style="background-color:black;color:white;text-align:left;">  18:45 Trattamento <span style="color:cyan;float:right;">AGGIUNGI NOTA </span></div><p>oppure Misura capillare.</p><div style="background-color:black;color:white;text-align:left;">  10:06 85 mg/dl <span style="color:cyan;float:right;">MISURA CAPILLARE </span></div><ul><li>Puoi inserire una nota o toccare CANCELLA per eliminare la voce. Vale per misure capillari, carboidrati e insulina.</li></ul><div class="admonition xdripitem"><p class="admonition-title">Note di Terapia</p><p><span style="color:cyan;">_____________________________________________________________________________________</span><br><small>Inserimento vocale di default dal prossimo</small> ☐</p><p><span style="color:cyan;float:left;">CANCELLA </span><span style="color:cyan;float:right;">ANNULLA FATTO </span></p></div><p>Nota che se tocchi una misura capillare e la modifichi, puoi anche convertirla in calibrazione con CALIBRA. È possibile se non hai selezionato <strong>Never use them</strong> (non usarle mai) in <a href="./../calibrate/advancedcal.html">Calibrazione avanzata</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Azione su misura capillare</p><p>Che cosa vorresti fare?</p><p><span style="color:cyan;float:left;">NIENTE </span><span style="color:cyan;float:right;">CANCELLA CALIBRA </span></p></div><h5 id="spoken-treatments" tabindex="-1">Trattamenti vocali <a class="header-anchor" href="#spoken-treatments" aria-label="Permalink to &quot;Trattamenti vocali {#spoken-treatments}&quot;">​</a></h5><p>Puoi usare l&#39;icona del microfono per inserire a voce i trattamenti o i comandi avanzati.</p><p>Un tocco prolungato sull&#39;icona del microfono ti permette di scrivere i <a href="./spokencommands.html">comandi avanzati</a>.</p><h3 id="treatment-notes" tabindex="-1">Note di terapia <a class="header-anchor" href="#treatment-notes" aria-label="Permalink to &quot;Note di terapia {#treatment-notes}&quot;">​</a></h3><p>Indipendentemente dai trattamenti, puoi inserire delle note.</p><img src="'+g+'" style="zoom:75%;"><p>Inserisci il commento che vuoi (ad esempio le unità di insulina lenta), oppure usa l&#39;icona del microfono per dettare la nota.</p><div class="admonition xdripitem"><p class="admonition-title">Note di Terapia</p><p><span style="color:cyan;">_____________________________________________________________________________________</span><br><small>Inserimento vocale di default dal prossimo</small> ☐</p><p><span style="color:cyan;float:left;">CANCELLA </span><span style="color:cyan;float:right;">ANNULLA FATTO </span></p></div><p>Verranno aggiunte al grafico così:</p><img src="'+f+'" style="zoom:75%;"><p>Toccandole puoi modificarle o eliminarle.</p><h3 id="undo-and-redo" tabindex="-1">Annulla e Ripeti <a class="header-anchor" href="#undo-and-redo" aria-label="Permalink to &quot;Annulla e Ripeti {#undo-and-redo}&quot;">​</a></h3><ol><li>Annulla torna indietro passo per passo tra simulazioni di trattamenti, calibrazioni e note. Dopo 30 minuti si nasconde di nuovo.</li><li>Ripeti va avanti passo per passo tra simulazioni di trattamenti, calibrazioni e note. Dopo 30 minuti si nasconde di nuovo.</li></ol><img src="'+b+'" style="zoom:77%;"><h3 id="main-menu" tabindex="-1"><a href="./hamburger.html">Menu principale</a> <a class="header-anchor" href="#main-menu" aria-label="Permalink to &quot;[Menu principale](./hamburger) {#main-menu}&quot;">​</a></h3><p>Chiamato anche menu hamburger o menu a scomparsa, è il menu principale in cui trovi o aggiungi le azioni più comuni, oltre a tutte le impostazioni e personalizzazioni.</p><img src="'+I+'" style="zoom:75%;"><h3 id="blood-drop-menu" tabindex="-1">Menu goccia di sangue <a class="header-anchor" href="#blood-drop-menu" aria-label="Permalink to &quot;Menu goccia di sangue {#blood-drop-menu}&quot;">​</a></h3><p>Con un tocco prolungato nell&#39;area centrale tra il menu principale e il menu a tre puntini, apri un altro menu per personalizzare l&#39;interfaccia utente.</p><img src="'+N+'" style="zoom:75%;"><h5 id="source-wizard-button" tabindex="-1">Pulsante Assistente Sorgente <a class="header-anchor" href="#source-wizard-button" aria-label="Permalink to &quot;Pulsante Assistente Sorgente {#source-wizard-button}&quot;">​</a></h5><p>Mostra il pulsante che ti guida nella scelta della sorgente dati, come descritto <a href="./../install/datasource.html">qui</a>.</p><div class="admonition xdripitem"><p class="admonition-title"><span style="background-color:grey;color:white;">   AVVIA CONFIGURAZIONE GUIDATA </span></p></div><h5 id="show-time-buttons" tabindex="-1">Mostrare Tasti Periodo <a class="header-anchor" href="#show-time-buttons" aria-label="Permalink to &quot;Mostrare Tasti Periodo {#show-time-buttons}&quot;">​</a></h5><p>Aggiunge una riga di quattro preimpostazioni per l&#39;intervallo di tempo del grafico principale: 24, 12, 6 e 3 ore.<br> Con una pressione prolungata su un pulsante del periodo puoi bloccare la vista su quel periodo.</p><div class="admonition xdripitem"><p class="admonition-title"><span style="background-color:grey;color:white;">  24 ORE </span>  <span style="background-color:grey;color:white;">  12 ORE </span>  <span style="background-color:grey;color:white;">  6 ORE </span>  <span style="background-color:grey;color:white;">  3 ORE </span></p></div><h5 id="locked-time-period-always-used" tabindex="-1">Usa Sempre Periodo Fisso <a class="header-anchor" href="#locked-time-period-always-used" aria-label="Permalink to &quot;Usa Sempre Periodo Fisso {#locked-time-period-always-used}&quot;">​</a></h5><p>Imposta come predefinito l&#39;ultimo periodo di visualizzazione modificato.</p><h5 id="show-chart-preview" tabindex="-1">Mostra Anteprima Grafico <a class="header-anchor" href="#show-chart-preview" aria-label="Permalink to &quot;Mostra Anteprima Grafico {#show-chart-preview}&quot;">​</a></h5><p>Attiva o disattiva il piccolo grafico delle 24 ore nella parte bassa dello schermo.</p><img src="'+z+'" style="zoom:75%;"><h5 id="show-collector-status" tabindex="-1">Mostra Stato Collettore <a class="header-anchor" href="#show-collector-status" aria-label="Permalink to &quot;Mostra Stato Collettore {#show-collector-status}&quot;">​</a></h5><p>Mostra sotto il grafico principale i messaggi informativi sullo stato del collector.</p><img src="'+v+'" style="zoom:75%;"><h5 id="show-sensor-expiry" tabindex="-1">Mostra Scadenza Sensore <a class="header-anchor" href="#show-sensor-expiry" aria-label="Permalink to &quot;Mostra Scadenza Sensore {#show-sensor-expiry}&quot;">​</a></h5><p>Mostra sotto il grafico principale il tempo rimanente prima della scadenza del sensore.</p><img src="'+y+'" style="zoom:75%;"><h5 id="show-graphical-trend-arrow" tabindex="-1">Mostra Freccia Di Tendenza Grafica <a class="header-anchor" href="#show-graphical-trend-arrow" aria-label="Permalink to &quot;Mostra Freccia Di Tendenza Grafica {#show-graphical-trend-arrow}&quot;">​</a></h5><p>Aggiunge un&#39;opzione che ti permette di scegliere altri stili di freccia.</p><p>Usa la chiave inglese <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_wrench_grey600_48dp.png" style="width:3%;"> e il menu a tendina ▼ per selezionarli.<br> Le frecce colorate includono un cursore della tonalità per cambiare colore.</p><p>L&#39;angolo delle frecce di tendenza grafiche dipende dalla differenza della lettura rispetto al valore precedente (5 minuti) e non solo piatto/45/90 gradi come le frecce classiche.</p><img src="'+q+'" style="zoom:90%;"><h3 id="three-dots-menu" tabindex="-1"><a href="./3dotsmenu.html">Menu a tre puntini</a> <a class="header-anchor" href="#three-dots-menu" aria-label="Permalink to &quot;[Menu a tre puntini](./3dotsmenu) {#three-dots-menu}&quot;">​</a></h3><p>Questo menu contiene alcune scorciatoie alle impostazioni e altre funzioni specifiche.</p><img src="'+L+'" style="zoom:75%;"><h3 id="widget" tabindex="-1">Widget <a class="header-anchor" href="#widget" aria-label="Permalink to &quot;Widget {#widget}&quot;">​</a></h3><p>Se il tuo telefono supporta i widget, fai un tocco prolungato su un&#39;area vuota della schermata Home e seleziona Widget.<br> Scorri le app finché trovi xDrip.</p><img src="'+w+'" style="zoom:75%;"><p>Tieni il dito sul widget e trascinalo nella posizione in cui vuoi visualizzarlo.</p><img src="'+k+'" style="zoom:75%;"><p>Puoi ridimensionarlo con i punti blu.</p><img src="'+x+'" style="zoom:75%;"><p>E dargli la dimensione che preferisci. Poi puoi personalizzarne i colori e l&#39;aspetto dei contenuti nelle <a href="./display.html">impostazioni di visualizzazione</a>.</p><img src="'+A+'" style="zoom:75%;"><h3 id="screensaver" tabindex="-1">Salvaschermo <a class="header-anchor" href="#screensaver" aria-label="Permalink to &quot;Salvaschermo {#screensaver}&quot;">​</a></h3><p>Se il tuo telefono supporta questa funzione, puoi attivare xDrip come salvaschermo nelle Impostazioni di Android.</p><img src="'+P+'" style="zoom:75%;"><p>Quando metti il telefono in carica, mostrerà un piccolo grafico e il valore della glicemia.</p><img src="'+T+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Ultima modifica 15/12/2024</em></a></p>',111)])])}const J=S(U,[["render",E]]);export{j as __pageData,J as default};
